346|    /// Load a Llama-style model from a GGUF file.
347|    pub fn load_gguf(path: &Path) -> Result<Self> {
348|        let _header = pesti_gguf::parser::parse_gguf(path)
349|            .map_err(|e| RunnerError::ModelLoad(e.to_string()))?;
350|        let weights = load_gguf_weights(path).map_err(|e| RunnerError::ModelLoad(e.to_string()))?;
351|        let mut model = Self::from_gguf_weights(weights)?;
352|
353|        // Load tokenizer from GGUF file
354|        if let Ok((tokenizer_config, tokenizer)) = load_tokenizer_from_gguf(path) {
355|            model.tokenizer_config = Some(tokenizer_config);
356|            model.tokenizer = Some(tokenizer);
357|            debug!(path = %path.display(), "Loaded model with tokenizer");
358|        } else {
359|            debug!(path = %path.display(), "No tokenizer found in GGUF file");
360|        }
361|
362|        Ok(model)
363|    }
364|
365|    /// Build a model from already-loaded GGUF weights.
366|    pub fn from_gguf_weights(weights: GgufWeights) -> Result<Self> {
367|        let header = &weights.header;
368|        let config = LlamaConfig::from_gguf_header(header)?;
369|
370|        let vocab_size = header.vocab_size();
371|        let rope_config = RopeConfig::new(config.head_dim, config.rope_base, config.max_seq_len);
372|
373|        // Load token embeddings — architecture-dependent name
374|        let embedding_name = config.embedding_name();
375|        let token_embeddings = weights.tensors.get(embedding_name).map(|tensor_data| {
376|            // For Qwen2, the embedding tensor shape is [embed_dim, vocab_size]
377|            // We need to set in_features = embed_dim for correct row lookup
378|            if matches!(config.arch, ModelArch::Qwen2 | ModelArch::Qwen3) {
379|                let embed_dim = config.embed_dim;
380|                Linear::from_f32_weight_with_shape(
381|                    tensor_data,
382|                    None,
383|                    embed_dim as usize,
384|                    vocab_size as usize * embed_dim as usize,
385|                )
386|            } else {
387|                Linear::from_f32_weight(tensor_data, None)
388|            }
389|        });
390|
391|        // Load output (LM head) — architecture-dependent name
392|        let output_name = config.output_name();
393|        let output = weights.tensors.get(output_name).map(|tensor_data| {
394|            // For Qwen2, output weight shape is [embed_dim, vocab_size] (transposed)
395|            // Linear layer expects [vocab_size, embed_dim], so we need to transpose
396|            // or interpret correctly. Here we set in_features=embed_dim, out_features=vocab_size
397|            if matches!(config.arch, ModelArch::Qwen2 | ModelArch::Qwen3) {
398|                let embed_dim = config.embed_dim;
399|                let vocab = vocab_size as usize;
400|                Linear::from_f32_weight_with_shape(tensor_data, None, embed_dim as usize, vocab)
401|            } else {
402|                Linear::from_f32_weight(tensor_data, None)
403|            }
404|        });
405|
406|        // Build transformer layers
407|        let mut layers = Vec::with_capacity(config.num_layers);
408|        for layer_idx in 0..config.num_layers {
409|            let layer = Self::load_layer(&weights, layer_idx, &config, &rope_config)?;
410|            layers.push(layer);
411|        }
412|
413|        // Load final norm for architectures that have it (qwen2/qwen3)
414|        let final_norm = if let Some(norm_name) = config.final_norm_name() {
415|            weights.tensors.get(norm_name).map(|tensor_data| {
416|                let weight: Vec<f32> = tensor_data
417|                    .chunks_exact(4)
418|                    .map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))
419|                    .collect();
420|                RmsNorm::new(weight, config.rms_norm_eps)
421|            })
422|        } else {
423|            None
424|        };
425|
426|        Ok(Self {
427|            config,
428|            token_embeddings,
429|            output,
430|            final_norm,
431|            layers,
432|            vocab_size,
433|            tokenizer: None,
434|            tokenizer_config: None,
435|            dispatch: Some(DispatchContext::new()),
436|            kv_caches: None,
437|            cpu_kv_caches: None,
438|        })
439|    }
440|
