16|/// Error type for conformance testing.
17|#[derive(Debug)]
18|pub enum ConformanceError {
19|    Io(std::io::Error),
20|    Utf8(std::string::FromUtf8Error),
21|    Parse(String),
22|    ModelLoad(String),
23|}
24|
25|impl From<std::io::Error> for ConformanceError {
26|    fn from(err: std::io::Error) -> Self {
27|        ConformanceError::Io(err)
28|    }
29|}
30|
31|impl From<std::string::FromUtf8Error> for ConformanceError {
32|    fn from(err: std::string::FromUtf8Error) -> Self {
33|        ConformanceError::Utf8(err)
34|    }
35|}
36|
37|impl From<pesti_runner::RunnerError> for ConformanceError {
38|    fn from(err: pesti_runner::RunnerError) -> Self {
39|        ConformanceError::ModelLoad(format!("Runner error: {}", err))
40|    }
41|}
42|
43|type Result<T> = std::result::Result<T, ConformanceError>;
44|
45|/// Configuration for a conformance test run.
46|#[derive(Debug)]
47|pub struct ConformanceConfig {
48|    /// Path to model corpus directory (GGUF files)
49|    pub corpus_dir: PathBuf,
50|    /// Reference llama.cpp binary path (optional)
51|    pub reference_llama_cpp: Option<PathBuf>,
52|    /// Expected minimum pass count (floor file threshold)
53|    pub floor_pass_count: usize,
54|    /// Floor file for CI gating (optional)
55|    pub floor_file: Option<PathBuf>,
56|}
57|
58|/// Result of running conformance tests.
59|#[derive(Debug)]
60|pub struct ConformanceResult {
61|    pub total_models: usize,
62|    pub passed: Vec<String>,
63|    pub failures: Vec<FailureInfo>,
64|}
65|
66|/// Information about a conformance failure.
67|#[derive(Debug, Clone)]
68|pub struct FailureInfo {
69|    /// Model name/path
70|    pub model_name: String,
71|    /// Expected output hash (from reference)
72|    pub expected_hash: String,
73|    /// Actual pesti output hash
74|    pub actual_hash: String,
75|}
76|
77|/// Run differential conformance tests against a corpus of models.
78|pub fn run_conformance(config: &ConformanceConfig) -> Result<ConformanceResult> {
79|    let models = discover_models(&config.corpus_dir)?;
80|
81|    if !models.is_empty() {
82|        tracing::info!(
83|            "Discovered {} models in {}",
84|            models.len(),
85|            config.corpus_dir.display()
86|        );
87|    }
88|
89|    // Load floor file if provided for CI gating
90|    let expected_pass_count = config.floor_file.as_ref().and_then(|path| {
91|        std::fs::read_to_string(path)
92|            .ok()
93|            .and_then(|content| content.trim().parse::<usize>().ok())
94|    });
95|
96|    if let Some(count) = expected_pass_count {
97|        tracing::info!("Loading floor file: {} models required", count);
98|    }
99|
100|    let mut passed: Vec<String> = vec![];
101|    let mut failures: Vec<FailureInfo> = vec![];
102|
103|    for model_path in &models {
104|        let model_name = model_path
105|            .file_stem()
106|            .and_then(|s| s.to_str())
107|            .unwrap_or("unknown")
108|            .to_string();
109|
110|        match run_single_model_conformance(model_path, config) {
111|            Ok(output_hash) => {
112|                tracing::info!("✓ PASS: {}", model_name);
113|                let hash_prefix = &output_hash[..8.min(output_hash.len())];
114|                passed.push(format!("{} - hash={}", model_name, hash_prefix));
115|            }
116|            Err(e) => {
117|                tracing::warn!("✗ FAIL: {} - {:?}", model_name, e);
118|                failures.push(FailureInfo {
119|                    model_name: model_name.clone(),
120|                    expected_hash: "unknown".to_string(),
121|                    actual_hash: format!("{:?}", e),
122|                });
123|            }
124|        }
125|    }
126|
127|    let total = passed.len() + failures.len();
128|
129|    tracing::info!(
130|        "Conformance complete: {}/{} passed ({:.1}%)",
131|        passed.len(),
132|        total,
133|        if total > 0 {
134|            (passed.len() as f64 / total as f64) * 100.0
135|        } else {
136|            0.0
137|        },
138|    );
139|
140|    let result = ConformanceResult {
141|        total_models: total,
142|        passed: passed.clone(),
143|        failures,
144|    };
145|
146|    // Write floor file if provided
147|    if let Some(floor_path) = &config.floor_file {
148|        write_floor_file(floor_path, passed.len())?;
149|    }
150|
151|    Ok(result)
152|}
