314|/// Discover all .gguf files in a directory (recursively).
315|fn discover_models(dir: &Path) -> Result<Vec<PathBuf>> {
316|    let mut models = Vec::new();
317|
318|    if dir.is_dir() {
319|        for entry in std::fs::read_dir(dir)? {
320|            let entry = entry?;
321|            let path = entry.path();
322|
323|            match path.extension().and_then(|s| s.to_str()) {
324|                Some("gguf") => models.push(path),
325|                _ if path.is_dir() => {
326|                    models.extend(discover_models(&path)?);
327|                }
328|                _ => {}
329|            }
330|        }
331|    } else if dir.exists() && path_ends_with(dir, ".gguf") {
332|        models.push(dir.to_path_buf());
333|    }
334|
335|    Ok(models)
336|}
337|
338|/// Check if a path ends with a specific suffix.
339|fn path_ends_with(path: &Path, suffix: &str) -> bool {
340|    path.file_name()
341|        .and_then(|s| s.to_str())
342|        .map(|name| name.ends_with(suffix))
343|        .unwrap_or(false)
344|}
345|
346|/// Write floor file with current pass count for CI gating.
347|fn write_floor_file(path: &Path, pass_count: usize) -> Result<()> {
348|    // Ensure parent directory exists
349|    if let Some(parent) = path.parent() {
350|        fs::create_dir_all(parent)?;
351|    }
352|
353|    // Write pass count to file
354|    let mut file = File::create(path)?;
355|    writeln!(file, "{}", pass_count)?;
356|
357|    tracing::info!("Wrote floor file: {} models passed", pass_count);
358|    Ok(())
359|}
