56|/// Stub argmax (mirrors real argmax from transformer/sampling.rs)
57|pub fn argmax(logits: &[f32]) -> u32 {
58|    logits
59|        .iter()
60|        .enumerate()
61|        .max_by(|(_, a), (_, b)| a.partial_cmp(b).unwrap())
62|        .map(|(i, _)| i as u32)
63|        .unwrap_or(0)
