66|/// Stub sample (mirrors real sample from transformer/sampling.rs)
67|pub fn sample(logits: &[f32], config: &SamplingConfig, rng: &mut rand::rngs::StdRng) -> u32 {
68|    let sum: f32 = logits.iter().map(|&x| x.exp()).sum();
69|    let probs: Vec<f32> = logits.iter().map(|&x| x.exp() / sum).collect();
70|
71|    // Use explicit distribution for rand 0.10+ compatibility
72|    let rng_seed = config.seed;
73|    let r = (rng_seed as f32) / u64::MAX as f32;
74|    let mut cumsum = 0.0;
75|    for (i, &p) in probs.iter().enumerate() {
76|        cumsum += p;
77|        if r < cumsum {
78|            return i as u32;
79|        }
80|    }
81|    (probs.len() - 1) as u32
82|}
