68|pub struct ModelLoader {
69|    pub conn: rusqlite::Connection,
70|}
71|
72|impl ModelLoader {
73|    pub fn new(conn: rusqlite::Connection) -> Self {
74|        Self { conn }
75|    }
76|
77|    /// Load weight manifest for a model from safetensors DB.
78|    pub fn load_manifest(&self, model_name: &str) -> Result<WeightManifest, RunnerError> {
79|        let mut stmt = self.conn.prepare(
80|            "SELECT id, model_name, repo_id, file_path, tensor_count, dtype, device, size_bytes, checksum, metadata, loaded_at, created_at, active FROM model_weights
81|             WHERE model_name = ?1 AND active = 1
82|             ORDER BY loaded_at DESC LIMIT 1",
83|        )?;
84|
85|        let row = stmt
86|            .query_row(rusqlite::params![model_name], |row| {
87|                let metadata_str: String = row.get(9)?;
88|                let metadata: serde_json::Value =
89|                    serde_json::from_str(&metadata_str).unwrap_or_default();
90|
91|                Ok(pesti_plug_in::manifest::ModelWeightRow {
92|                    id: row.get(0)?,
93|                    model_name: row.get(1)?,
94|                    repo_id: row.get(2)?,
95|                    file_path: row.get(3)?,
96|                    tensor_count: row.get(4)?,
97|                    dtype: row.get(5)?,
98|                    device: row.get(6)?,
99|                    size_bytes: row.get(7)?,
100|                    checksum: row.get(8)?,
101|                    metadata,
102|                    loaded_at: row.get(10)?,
103|                    created_at: row.get(11)?,
104|                    active: row.get(12)?,
105|                })
106|            })
107|            .map_err(RunnerError::Sqlite)?;
108|
109|        let mut tensor_stmt = self.conn.prepare(
110|            "SELECT id, weight_id, tensor_name, shape, dtype, size_bytes, checksum FROM tensor_metadata
111|             WHERE weight_id = ?1",
112|        )?;
113|
114|        let tensors: Vec<pesti_plug_in::manifest::TensorMetadataRow> = tensor_stmt
115|            .query_map(rusqlite::params![row.id], |row| {
116|                Ok(pesti_plug_in::manifest::TensorMetadataRow {
117|                    id: row.get(0)?,
118|                    weight_id: row.get(1)?,
119|                    tensor_name: row.get(2)?,
120|                    shape: row.get(3)?,
121|                    dtype: row.get(4)?,
122|                    size_bytes: row.get(5)?,
123|                    checksum: row.get(6)?,
124|                })
125|            })?
126|            .collect::<Result<Vec<_>, _>>()?;
127|
128|        let manifest = WeightManifest {
129|            weight_id: row.id,
130|            model_name: row.model_name,
131|            repo_id: row.repo_id,
132|            file_path: row.file_path,
133|            tensor_count: row.tensor_count,
134|            dtype: row.dtype,
135|            device: row.device,
136|            size_bytes: row.size_bytes,
137|            checksum: row.checksum,
138|            tensors,
139|            metadata: row.metadata,
140|            lazy_loading: true,
141|        };
142|
143|        debug!(
144|            model_name = %model_name,
145|            tensor_count = manifest.tensor_count,
146|            "Model loader: manifest loaded from safetensors DB"
147|        );
148|
149|        Ok(manifest)
150|    }
