154|        pesti_safetensors::schema::verify_weight_checksum(&self.conn, weight_id, expected).map_err(
155|            |_: SafetensorsSchemaError| RunnerError::Sqlite(rusqlite::Error::QueryReturnedNoRows),
156|        )
